using TMPro;
using UnityEngine;
using UnityEngine.UI;
public static class GridShiftUI {
 public static RectTransform Rect(string name,Transform parent,Vector2 size){GridShiftUILayout.Notify();var go=new GameObject(name,typeof(RectTransform));go.transform.SetParent(parent,false);var r=go.GetComponent<RectTransform>();r.sizeDelta=size;return r;}
 public static void Stretch(RectTransform r,Vector2 min,Vector2 max){r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=min;r.offsetMax=max;}
 public static TMP_Text Text(Transform parent,string value,int font=24,float height=38){var r=Rect("Label",parent,new Vector2(700,height));var t=r.gameObject.AddComponent<TextMeshProUGUI>();t.text=value;t.fontSize=font;t.color=Color.white;t.raycastTarget=false;t.enableWordWrapping=true;return t;}
 public static Button Button(Transform parent,string label,UnityEngine.Events.UnityAction action,float height=48,bool primary=false){var r=Rect(label,parent,new Vector2(700,height));r.gameObject.AddComponent<Image>();var b=r.gameObject.AddComponent<Button>();var text=Text(r,label,23,height);text.alignment=TextAlignmentOptions.Center;Stretch(text.rectTransform,new Vector2(52,3),new Vector2(-28,-3));b.onClick.AddListener(action);GridShiftUITheme.Button(b,primary);return b;}
 public static TMP_InputField Input(Transform parent,string label,bool password=false){Text(parent,label,21,30);var r=Rect(label,parent,new Vector2(700,55));GridShiftUITheme.Surface(r.gameObject.AddComponent<Image>(),"Campo_Email_Senha");r.GetComponent<Image>().raycastTarget=true;var field=r.gameObject.AddComponent<TMP_InputField>();var area=Rect("TextArea",r,Vector2.zero);Stretch(area,new Vector2(18,6),new Vector2(-18,-6));area.gameObject.AddComponent<RectMask2D>();var text=Text(area,"",24,40);Stretch(text.rectTransform,Vector2.zero,Vector2.zero);field.textViewport=area;field.textComponent=(TextMeshProUGUI)text;field.targetGraphic=r.GetComponent<Image>();field.contentType=password?TMP_InputField.ContentType.Password:TMP_InputField.ContentType.Standard;field.lineType=TMP_InputField.LineType.SingleLine;field.characterLimit=password?128:120;return field;}
 public static void Stack(RectTransform r,int padding=18,float spacing=10){var v=r.gameObject.AddComponent<VerticalLayoutGroup>();v.padding=new RectOffset(padding,padding,padding,padding);v.spacing=spacing;v.childControlWidth=true;v.childControlHeight=false;v.childForceExpandHeight=false;r.gameObject.AddComponent<ContentSizeFitter>().verticalFit=ContentSizeFitter.FitMode.PreferredSize;}
 public static RectTransform Card(Transform parent,string title,float height){var r=Rect(title,parent,new Vector2(700,height));GridShiftUITheme.Surface(r.gameObject.AddComponent<Image>(),"Painel_Cartao_Informacoes");var v=r.gameObject.AddComponent<VerticalLayoutGroup>();v.padding=new RectOffset(22,22,18,18);v.spacing=7;v.childControlWidth=true;v.childControlHeight=false;v.childForceExpandHeight=false;Text(r,title,26,38).color=new Color(1,.83f,.2f);return r;}
 public static RectTransform Scroll(Transform parent,Vector2 min,Vector2 max,out ScrollRect scroll){var r=Rect("Scroll",parent,Vector2.zero);Stretch(r,min,max);scroll=r.gameObject.AddComponent<ScrollRect>();scroll.horizontal=false;scroll.movementType=ScrollRect.MovementType.Clamped;scroll.scrollSensitivity=40;var viewport=Rect("Viewport",r,Vector2.zero);Stretch(viewport,Vector2.zero,Vector2.zero);viewport.gameObject.AddComponent<Image>().color=Color.clear;viewport.gameObject.AddComponent<RectMask2D>();var content=Rect("Content",viewport,Vector2.zero);content.anchorMin=new Vector2(0,1);content.anchorMax=Vector2.one;content.pivot=new Vector2(.5f,1);content.offsetMin=content.offsetMax=Vector2.zero;Stack(content);scroll.viewport=viewport;scroll.content=content;return content;}
}
